<template><view class="support"><view v-if="error" class="card">{{error}}<button class="ui-button" @click="load(false)">重试</button></view><view v-if="session" class="card"><view>{{session.status==='closed'?'会话已结束，发送留言可重新开始':session.assigned_to?'客服已接待':'等待客服接待'}}</view><text class="hint">服务时间：{{session.settings.weekdaysOnly?'工作日':'每天'}} {{session.settings.startHour}}:00—{{session.settings.endHour}}:00</text><view v-if="!session.settings.working" class="hint">{{session.settings.offlineText}}</view></view><view class="row"><button class="ui-button" v-if="hasOlder" :disabled="loading" @click="load(true)">查看更早消息</button><button class="ui-button" v-if="history" :disabled="loading" @click="history=false;load(false)">返回最新消息</button></view><view v-for="m in rows" :key="m.id" class="bubble" :class="{mine:m.sender==='member'}"><text class="hint">{{m.sender==='member'?'我':'客服'}} · {{formatDate(m.created_at)}}</text><view v-if="m.body">{{m.body}}</view><image v-if="m.image_id&&images[m.image_id]" :src="images[m.image_id]" mode="widthFix" @click="preview(images[m.image_id])"/><button class="ui-button" v-else-if="m.image_id" @click="loadImage(m.image_id)">查看图片</button><button class="ui-button" v-if="m.order_id" @click="go('order-detail',{id:m.order_id})">查看关联订单</button></view><view v-if="!rows.length" class="card">请描述遇到的问题，也可以附上图片和关联订单。</view><view class="composer" :style="{bottom:keyboardHeight+'px'}"><picker :range="orderOptions" range-key="label" @change="orderId=orderOptions[Number($event.detail.value)].id"><view class="input">{{orderOptions.find(o=>o.id===orderId)?.label||'不关联订单'}} ›</view></picker><textarea v-model="body" maxlength="2000" placeholder="请输入想咨询的问题" :adjust-position="false" @keyboardheightchange="keyboardHeight=$event.detail.height||0" @blur="keyboardHeight=0"/><view class="row"><button class="ui-button" :disabled="busy" @click="choose">{{imageId?'已选择图片，点击更换':'添加图片'}}</button><button class="ui-button" :disabled="busy||(!body.trim()&&!imageId)" @click="send">发送</button></view></view></view></template>
<script>
import {formatDate} from '../services/display'
import {uploadSupportImage,request,notify,API_BASE,getToken,go} from '../services/shop.js'
export default {props:{active:{type:Boolean,default:true}},data(){return{session:null,chatLoaded:false,scrollAfterSend:false,hasOlder:false,keyboardHeight:0,rows:[],images:{},orders:[],error:'',body:'',orderId:0,imageId:0,busy:false,loading:false,history:false,key:'',lastPayload:'',version:0}},computed:{orderOptions(){return[{id:0,label:'不关联订单'},...this.orders.map(o=>({id:o.id,label:'订单 '+o.order_no}))]}},watch:{active:{immediate:true,handler(v){clearInterval(this.timer);if(v){this.load(false);this.timer=setInterval(()=>{if(!this.history&&!this.busy)this.load(false)},10000)}}}},beforeUnmount(){clearInterval(this.timer);this.closed=true;this.clearImages()},methods:{go,formatDate,clearImages(){
// #ifdef H5
for(const url of Object.values(this.images))URL.revokeObjectURL(url);
// #endif
this.images={}},async load(older){if(!this.active||this.loading&&older)return;const version=++this.version;this.loading=true;try{const before=older&&this.rows.length?this.rows[0].id:0;const r=await request('/support'+(before?'?before='+before:''));if(version!==this.version||this.closed||!this.active)return;if(older&&!r.messages.length){this.hasOlder=false;return;}this.hasOlder=r.messages.length===50;this.history=!!older;this.session=r;this.rows=r.messages;if(!older&&(!this.chatLoaded||this.scrollAfterSend)){this.$nextTick(()=>uni.pageScrollTo({scrollTop:100000,duration:0}));this.scrollAfterSend=false}this.chatLoaded=true;const needed=new Set(this.rows.map(m=>String(m.image_id)));for(const id of Object.keys(this.images))if(!needed.has(id)){
// #ifdef H5
URL.revokeObjectURL(this.images[id]);
// #endif
delete this.images[id];}this.error='';if(!older&&this.rows.length)await request('/support/read','POST',{lastId:this.rows[this.rows.length-1].id});if(!this.orders.length)this.orders=await request('/orders');for(const m of this.rows)if(m.image_id)this.loadImage(m.image_id)}catch(e){this.error=e.message}finally{if(version===this.version)this.loading=false}},async loadImage(id){if(this.images[id])return;const version=this.version,url=API_BASE+'/shop/app/support/images/'+id,header={'X-Shop-Token':'Bearer '+getToken()};try{let path;
// #ifdef H5
const r=await fetch(url,{headers:header});if(!r.ok||!r.headers.get('content-type')?.includes('image/'))throw Error('图片加载失败');path=URL.createObjectURL(await r.blob());if(this.closed||version!==this.version){URL.revokeObjectURL(path);return;}
// #endif
// #ifndef H5
path=await new Promise((resolve,reject)=>uni.downloadFile({url,header,success:r=>r.statusCode===200?resolve(r.tempFilePath):reject(Error('图片加载失败')),fail:()=>reject(Error('图片加载失败'))}));if(this.closed||version!==this.version)return;
// #endif
this.images[id]=path}catch(e){notify(e)}},preview(path){uni.previewImage({urls:[path]})},choose(){if(this.busy)return;uni.chooseImage({count:1,sizeType:['compressed'],success:async r=>{this.busy=true;try{const result=await uploadSupportImage(r.tempFilePaths[0]);this.imageId=result.id;this.key=''}catch(e){notify(e)}finally{this.busy=false}},fail:e=>{if(!/cancel/i.test(e.errMsg||''))notify('选图失败，请重试')}})},async send(){if(this.busy)return;this.busy=true;try{const payload={body:this.body,imageId:this.imageId,orderId:this.orderId},signature=JSON.stringify(payload);if(!this.key||signature!==this.lastPayload){this.key='chat_'+Date.now()+'_'+Math.random().toString(36).slice(2);this.lastPayload=signature}await request('/support/messages','POST',{...payload,requestKey:this.key});this.body='';this.imageId=0;this.key='';this.history=false;this.scrollAfterSend=true;await this.load(false)}catch(e){notify(e)}finally{this.busy=false}}}}
</script>
<style scoped>
@import '../styles/component-base.css';
.support{padding:16px;font-size:16px}.card,.bubble,.composer{background:var(--shop-surface, #fdfeff);border-radius:12px;padding:16px;margin-bottom:12px;line-height:1.8;overflow-wrap:anywhere}.bubble.mine{background:var(--shop-soft, #eaf5fb);margin-left:24px}.bubble:not(.mine){margin-right:24px}.heading{font-size:20px;font-weight:bold}.hint{display:block;font-size:13px;color:var(--shop-ink, #28546c)}.row{display:flex;gap:10px}.row button{flex:1;font-size:15px;margin:8px 0}.input,textarea{background:var(--shop-background, #f3f8fb);padding:12px;width:auto;margin-bottom:12px}button{font-size:15px;background:var(--shop-accent, #c7e8f5);color:var(--shop-ink, #28546c)}image{width:100%;max-width:280px;display:block;margin:10px 0}.support{padding:12px 12px calc(230px + env(safe-area-inset-bottom));font-size:14px}.card,.bubble{padding:12px;border-radius:10px}.hint{font-size:11px}.composer{position:fixed;left:0;right:0;z-index:30;border-radius:0;margin:0;padding:10px 12px calc(10px + env(safe-area-inset-bottom));border-top:1px solid var(--shop-border, #d5e6ee);background:var(--shop-surface, #fdfeff)}.composer textarea{width:100%;height:60px;min-height:60px;box-sizing:border-box;margin-bottom:4px;font-size:14px;padding:10px;border-radius:6px}.composer .input{font-size:12px;padding:6px 10px;margin-bottom:7px}.composer .row button{font-size:13px;line-height:34px;margin:3px 0}.composer .row button:first-child{background:var(--shop-background, #f3f8fb);color:var(--shop-ink, #28546c)}.support>.row button{background:transparent;color:var(--shop-muted, #59727f);font-size:12px;line-height:30px}.bubble image{max-width:200px}@media(min-width:600px){.composer{max-width:430px;box-sizing:border-box;margin:auto}}</style>
